begin;

create table if not exists public.busan_administrative_region (
    region_code varchar(10) primary key,
    region_name varchar(50) not null unique,
    region_type varchar(20) not null,
    display_order integer not null
);

comment on table public.busan_administrative_region is 'Busan city and district/gun master data for map statistics';

insert into public.busan_administrative_region (region_code, region_name, region_type, display_order)
