    ('26350', '해운대구', 'DISTRICT', 9),
    ('26380', '사하구', 'DISTRICT', 10),
    ('26410', '금정구', 'DISTRICT', 11),
    ('26440', '강서구', 'DISTRICT', 12),
    ('26470', '연제구', 'DISTRICT', 13),
