on conflict (region_code) do update set
    region_name = excluded.region_name,
    region_type = excluded.region_type,
    display_order = excluded.display_order;

create table if not exists public.busan_industry_employment_source_file (
    source_file_id bigint primary key,
    file_name varchar(500) not null,
    file_hash varchar(64) not null unique,
    source_table_id varchar(100) not null,
    source_table_name varchar(300) not null,
    source_period varchar(100),
    source_name varchar(300),
    downloaded_at_text varchar(100),
    source_url varchar(1000),
    source_note text,
    imported_at timestamptz not null default now()
);

comment on table public.busan_industry_employment_source_file is 'KOSIS Excel files used for Busan district by industry employment statistics';

insert into public.busan_industry_employment_source_file
    (source_file_id, file_name, file_hash, source_table_id, source_table_name, source_period, source_name, downloaded_at_text, source_url, source_note)
values
    (1, '산업소분류_및_구·군별_사업체수__종사자수_20260725210531.xlsx', '5aefcc55a26e8753ff717351c1cc96c18abde71ec0b961ac954ca5f35d9bca61', 'DT_C10131', '산업소분류 및 구·군별 사업체수, 종사자수', '[년] 2023~2023  ', '「부산광역시사업체조사」, 부산광역시', '2026.07.25 21:05', 'https://kosis.kr/statHtml/statHtml.do?orgId=202&tblId=DT_C10131&conn_path=I3', '주: 『X』는 하나의 산업분류별 2개 이하인 사업체는 사업체의 비밀보호를 위하여 종사자 수를 X표시함.'),
    (2, '산업소분류_및_구·군별_사업체수__종사자수_20260725210549.xlsx', 'df2290bd92f1a596521b1aad9c0262bb4994dbf16ea3c3d31e3b2c4a9c8ac720', 'DT_C10132', '산업소분류 및 구·군별 사업체수, 종사자수', '[년] 2024~2024  ', '「부산광역시사업체조사」, 부산광역시', '2026.07.25 21:05', 'https://kosis.kr/statHtml/statHtml.do?orgId=202&tblId=DT_C10132&conn_path=I3', '주: 『X』는 하나의 산업분류별 2개 이하인 사업체는 사업체의 비밀보호를 위하여 종사자 수를 X표시함.')
on conflict (source_file_id) do update set
    file_name = excluded.file_name,
    file_hash = excluded.file_hash,
    source_table_id = excluded.source_table_id,
    source_table_name = excluded.source_table_name,
    source_period = excluded.source_period,
    source_name = excluded.source_name,
    downloaded_at_text = excluded.downloaded_at_text,
    source_url = excluded.source_url,
    source_note = excluded.source_note;

create table if not exists public.busan_district_industry_employment_stat (
    stat_id bigint generated by default as identity primary key,
    year integer not null,
    is_provisional boolean not null default false,
    region_code varchar(10) not null references public.busan_administrative_region(region_code),
    region_name varchar(50) not null,
    sgg varchar(10) not null,
    sggnm varchar(50) not null,
    parent_industry_name varchar(300),
    industry_name varchar(300) not null,
    ksic_level varchar(20) not null,
    section_code varchar(1),
    division_code varchar(2),
    establishment_count integer,
    employee_count integer,
    establishment_count_suppressed boolean not null default false,
    employee_count_suppressed boolean not null default false,
    source_file_id bigint not null references public.busan_industry_employment_source_file(source_file_id),
    source_row_number integer,
    source_column_name varchar(150),
    created_at timestamptz not null default now(),
    constraint ck_busan_district_industry_ksic_level check (ksic_level in ('TOTAL', 'SECTION', 'DIVISION')),
    constraint uk_busan_district_industry_employment_stat unique (year, region_code, ksic_level, industry_name)
);

comment on table public.busan_district_industry_employment_stat is 'Busan region/district industry establishment and employee counts by year from KOSIS';
comment on column public.busan_district_industry_employment_stat.sgg is 'City/district code aligned with GeoJSON properties.sgg';
comment on column public.busan_district_industry_employment_stat.sggnm is 'City/district name aligned with GeoJSON properties.sggnm';
comment on column public.busan_district_industry_employment_stat.ksic_level is 'TOTAL for all industries, SECTION for KSIC large section, DIVISION for KSIC middle division';
comment on column public.busan_district_industry_employment_stat.section_code is 'KSIC section code for joins to ksic_info.section_code';
comment on column public.busan_district_industry_employment_stat.division_code is 'KSIC division code for joins to ksic_info.division_code';

create index if not exists idx_busan_district_industry_emp_year_region on public.busan_district_industry_employment_stat (year, region_code);
create index if not exists idx_busan_district_industry_emp_section on public.busan_district_industry_employment_stat (section_code);
create index if not exists idx_busan_district_industry_emp_division on public.busan_district_industry_employment_stat (division_code);
create index if not exists idx_busan_district_industry_emp_industry_name on public.busan_district_industry_employment_stat (industry_name);

