ksic_sections as (
    select section_code, max(section_name) as section_name
    from public.ksic_info
    where section_code is not null
    group by section_code
),
ksic_divisions as (
    select division_code, max(division_name) as division_name, max(section_code) as section_code
    from public.ksic_info
    where division_code is not null
    group by division_code
),
ksic_division_aliases as (
    values
        ('방송업', '60'),
        ('보험및연금업', '65')
)
insert into public.busan_district_industry_employment_stat
    (year, is_provisional, region_code, region_name, sgg, sggnm, parent_industry_name, industry_name, ksic_level, section_code, division_code, establishment_count, employee_count, establishment_count_suppressed, employee_count_suppressed, source_file_id, source_row_number, source_column_name)
select
    source_rows.year,
    source_rows.is_provisional,
    source_rows.region_code,
    source_rows.region_name,
    source_rows.region_code as sgg,
    source_rows.region_name as sggnm,
    source_rows.parent_industry_name,
    source_rows.industry_name,
    source_rows.ksic_level,
    case
        when source_rows.ksic_level = 'SECTION' then ksic_sections.section_code
        when source_rows.ksic_level = 'DIVISION' then ksic_divisions.section_code
        else null
    end as section_code,
    case when source_rows.ksic_level = 'DIVISION' then ksic_divisions.division_code else null end as division_code,
    source_rows.establishment_count,
    source_rows.employee_count,
    source_rows.establishment_count_suppressed,
    source_rows.employee_count_suppressed,
    source_rows.source_file_id,
    source_rows.source_row_number,
    source_rows.source_column_name
from source_rows
left join ksic_sections
  on source_rows.ksic_level = 'SECTION'
 and replace(ksic_sections.section_name, ' ', '') = replace(source_rows.industry_name, ' ', '')
left join ksic_divisions
  on source_rows.ksic_level = 'DIVISION'
 and ksic_divisions.division_code = coalesce(
        (
            select alias.column2
            from ksic_division_aliases alias
            where replace(alias.column1, ' ', '') = replace(source_rows.industry_name, ' ', '')
            limit 1
        ),
        ksic_divisions.division_code
    )
 and (
        replace(ksic_divisions.division_name, ' ', '') = replace(source_rows.industry_name, ' ', '')
     or exists (
            select 1
            from ksic_division_aliases alias
            where alias.column2 = ksic_divisions.division_code
              and replace(alias.column1, ' ', '') = replace(source_rows.industry_name, ' ', '')
        )
    )
on conflict (year, region_code, ksic_level, industry_name) do update set
    is_provisional = excluded.is_provisional,
    region_name = excluded.region_name,
    sgg = excluded.sgg,
    sggnm = excluded.sggnm,
    parent_industry_name = excluded.parent_industry_name,
    section_code = excluded.section_code,
    division_code = excluded.division_code,
    establishment_count = excluded.establishment_count,
    employee_count = excluded.employee_count,
    establishment_count_suppressed = excluded.establishment_count_suppressed,
    employee_count_suppressed = excluded.employee_count_suppressed,
    source_file_id = excluded.source_file_id,
    source_row_number = excluded.source_row_number,
    source_column_name = excluded.source_column_name;

create or replace view public.v_busan_district_industry_employment_growth as
select
    curr.year,
    curr.is_provisional,
    curr.region_code,
    curr.region_name,
    curr.sgg,
    curr.sggnm,
    region.region_type,
    curr.parent_industry_name,
    curr.industry_name,
    curr.ksic_level,
    curr.section_code,
    curr.division_code,
    curr.establishment_count as current_establishment_count,
    prev.establishment_count as previous_establishment_count,
    curr.employee_count as current_employee_count,
    prev.employee_count as previous_employee_count,
    case
        when prev.establishment_count is null or prev.establishment_count = 0 then null
        else round(((curr.establishment_count - prev.establishment_count) * 100.0 / prev.establishment_count)::numeric, 2)
    end as establishment_growth_rate,
    case
        when prev.employee_count is null or prev.employee_count = 0 then null
        else round(((curr.employee_count - prev.employee_count) * 100.0 / prev.employee_count)::numeric, 2)
    end as employee_growth_rate
from public.busan_district_industry_employment_stat curr
join public.busan_administrative_region region on region.region_code = curr.region_code
left join public.busan_district_industry_employment_stat prev
  on prev.year = curr.year - 1
 and prev.region_code = curr.region_code
 and prev.ksic_level = curr.ksic_level
 and prev.industry_name = curr.industry_name;

create or replace view public.v_busan_district_industry_employment_ksic as
select
    stat.*,
    section_ref.section_name as ksic_section_name,
    division_ref.division_name as ksic_division_name,
    division_ref.sample_ksic_code as sample_ksic_code_for_join
from public.busan_district_industry_employment_stat stat
left join (
    select section_code, max(section_name) as section_name
    from public.ksic_info
    where section_code is not null
    group by section_code
) section_ref on section_ref.section_code = stat.section_code
left join (
    select division_code, max(division_name) as division_name, min(ksic_code) as sample_ksic_code
    from public.ksic_info
    where division_code is not null
    group by division_code
) division_ref on division_ref.division_code = stat.division_code;

commit;
